<?php
declare(strict_types=1);
require __DIR__.'/inc/db.php';require __DIR__.'/inc/page.php';
$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$cakes=[];
if($search!==''){$term='%'.$search.'%';$q=$pdo->prepare("SELECT c.*,cat.name category FROM cakes c LEFT JOIN categories cat ON cat.id=c.category_id WHERE c.available=1 AND (c.name LIKE ? OR COALESCE(c.description,'') LIKE ? OR c.cake_id LIKE ?) ORDER BY c.name LIMIT 100");$q->execute([$term,$term,$term]);$cakes=$q->fetchAll();}
page_start('Search cakes');
?><main class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="eyebrow">Our menu</div><h1 class="h3">Search cakes</h1></div><a href="view-all.php" class="btn btn-outline-primary">Back to menu</a></div><form method="get" class="app-card p-3 d-flex gap-2 mb-4"><label class="visually-hidden" for="q">Search cakes</label><input id="q" type="search" name="q" maxlength="100" class="form-control" value="<?=e($search)?>" placeholder="Search by cake name or description"><button class="btn btn-purple">Search</button></form><?php if($search===''):?><div class="app-card p-5 text-center"><h2 class="h5">Find a cake</h2><p class="help-text mb-0">Enter a name or description above.</p></div><?php elseif(!$cakes):?><div class="alert alert-info">No cakes matched your search.</div><?php else:?><p class="text-muted"><?=count($cakes)?> result<?=count($cakes)===1?'':'s'?> for <strong><?=e($search)?></strong></p><div class="row g-4"><?php foreach($cakes as $cake):?><div class="col-sm-6 col-lg-4"><article class="app-card h-100 overflow-hidden"><?php if($cake['picture']):?><img src="uploads/<?=e(basename((string)$cake['picture']))?>" class="w-100" style="height:220px;object-fit:cover" alt="<?=e($cake['name'])?>"><?php endif;?><div class="p-3"><div class="small text-muted"><?=e($cake['category']??'Cake')?></div><h2 class="h5"><?=e($cake['name'])?></h2><p><?=e(mb_substr((string)$cake['description'],0,120))?></p><div class="d-flex justify-content-between align-items-center"><strong>&#8369;<?=number_format((float)$cake['price'],2)?></strong><?php if((int)$cake['quantity']>0):?><a href="cake_add.php?id=<?=(int)$cake['id']?>" class="btn btn-purple">Customize</a><?php else:?><span class="badge text-bg-secondary">Out of stock</span><?php endif;?></div></div></article></div><?php endforeach;?></div><?php endif;?></main><footer class="text-center py-4 text-muted small">&copy; <?=date('Y')?> Aure Sanchez House of Cakes</footer><?php page_end();
